INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cómo define el Código Civil y Comercial al derecho real?', '["Como un acuerdo de voluntades entre el Estado y los particulares.", "Como el poder jurídico, de estructura legal, que se ejerce directamente sobre su objeto en forma autónoma .", "Como la facultad de exigir una prestación de dar, hacer o no hacer al Estado.", "Como una mera tenencia precaria de bienes públicos."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es la finalidad principal de los derechos reales administrativos?', '["Generar lucro para las arcas del Tesoro Nacional.", "Satisfacer intereses puramente individuales de los funcionarios.", "Satisfacer necesidades o intereses colectivos .", "Regular las relaciones de vecindad entre propietarios privados."]'::jsonb, 2, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Quién es siempre el titular de los derechos reales administrativos?', '["El pueblo, de manera directa e inalienable.", "Cualquier ciudadano que haga uso de un bien público.", "El Estado en sentido amplio (Nación, provincias, municipalidades, etc.) .", "Las empresas privadas concesionarias de servicios."]'::jsonb, 2, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué vertientes comprende el derecho real de propiedad estatal?', '["Solo los bienes de uso común.", "El dominio público y el dominio privado del Estado .", "Únicamente los bienes inmuebles por naturaleza.", "Los bienes de los particulares afectados a una servidumbre."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cómo se clasifican los bienes del Estado según su origen?', '["Nacionales y extranjeros.", "Terrestres, hídricos y aéreos.", "Naturales (playas, ríos) y artificiales (obras públicas) .", "Muebles e inmuebles únicamente."]'::jsonb, 2, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué postura doctrinaria niega la existencia de una relación real de propiedad y afirma un intenso poder reglamentario?', '["El dominio público como derecho de propiedad.", "El dominio público potestad o título de intervención .", "La postura ecléctica o intermedia.", "El dominio público como derecho de la colectividad."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', 'Según Bielsa, ¿quién es el titular del dominio público?', '["El Estado como persona jurídica.", "El Poder Ejecutivo por delegación.", "El pueblo .", "Los jueces administrativos."]'::jsonb, 2, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué criterio sostiene Fiorini sobre la medida de los bienes estatales?', '["Se miden por su valor económico en el mercado.", "Se miden por su escasez geográfica.", "Se miden por sus fines, no por su valor económico .", "No pertenecen al patrimonio del Estado."]'::jsonb, 2, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál de los siguientes es un bien del dominio público según el art. 235 del CCyC?', '["Los bienes de las sucesiones vacantes.", "El mar territorial, aguas interiores, ríos, estuarios y arroyos .", "Los muebles de las oficinas de administración central.", "Las minas de oro y plata."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué se entiende por "playas marítimas" según el Código?', '["Toda la tierra hasta los 500 metros del mar.", "La porción de tierra que las mareas bañan y desocupan durante las más altas y bajas mareas normales .", "Las zonas de puertos construidas por el hombre.", "Únicamente los balnearios concesionados."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es el "Elemento Subjetivo" de los bienes dominiales?', '["Que son \\\"res nullius\\\" (no pertenecen a nadie).", "Que pertenecen a la persona jurídica pública Estado (Nación, Provincia o Municipio) .", "El interés particular del vecino lindero.", "El permiso de uso otorgado al particular."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué comprende el "Elemento Objetivo" en una plaza pública?', '["Solo la superficie de la tierra.", "El subsuelo, el espacio aéreo y sus muebles accesorios (árboles, bancos, luminarias) .", "Únicamente las estatuas de próceres.", "Solo el edificio municipal lindero."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿A qué hace referencia el "Elemento Teleológico" de los bienes públicos?', '["A la norma legal que los creó.", "Al destino de uso común o utilidad pública .", "Al costo de su mantenimiento anual.", "A la nacionalidad del constructor."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuáles son los caracteres de los bienes públicos del Estado según el art. 237 del CCyC?', '["Enajenables, embargables y prescriptibles.", "Inenajenables, inembargables e imprescriptibles .", "Privados, secretos e invisibles.", "Temporales, onerosos y revocables sin causa."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cómo se produce la afectación de los bienes públicos NATURALES?', '["Mediante una ceremonia de inauguración.", "Por el uso de los vecinos durante 20 años.", "Se concreta \\\"ministerio legis\\\" desde su inclusión en la nómina legal .", "Por decreto del Intendente local."]'::jsonb, 2, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué requisito adicional necesitan los bienes ARTIFICIALES para ser del dominio público?', '["Solo figurar en el Código Civil.", "Un hecho (inauguración) o una manifestación de voluntad estatal de efectiva consagración al uso .", "Ser comprados con moneda extranjera.", "Que un particular los reclame como propios."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué es un edificio destinado a hospital mientras no sea efectivamente consagrado al uso público?', '["Un bien del dominio público.", "Un bien del dominio privado del Estado .", "Un bien de propiedad privada de los médicos.", "Un bien sin dueño hasta que se inaugure."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué significa "desafectar" un bien del dominio público?', '["Repararlo para que funcione mejor.", "Sustraerlo de su destino al uso público, pasando al dominio privado .", "Cobrar una entrada para ingresar al mismo.", "Cambiarle el nombre oficial mediante ordenanza."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cómo pueden desafectarse los bienes del dominio público NATURAL?', '["Por decisión de la asamblea de vecinos.", "Por el simple paso del tiempo si nadie los usa.", "Solo por ley formal del Congreso Nacional modificando la ley civil .", "Por resolución de un juez de faltas."]'::jsonb, 2, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es la diferencia entre "uso común" y "uso especial" del dominio público?', '["El común es pago y el especial gratuito.", "El común lo disfruta cualquier persona como tal; el especial requiere título (permiso o concesión) .", "El común es para funcionarios y el especial para el pueblo.", "No existe diferencia legal entre ambos."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué carácter tiene generalmente el "permiso de uso" de un bien público?', '["Es un contrato perpetuo e irrevocable.", "Se otorga mediante acto administrativo unilateral y es esencialmente precario (revocable) .", "Requiere siempre una ley del Congreso para otorgarse.", "Es una venta encubierta del bien estatal."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué caracteriza a la "concesión de uso" de un bien público?', '["Es un acto unilateral y siempre gratuito.", "Es un contrato administrativo, oneroso y sujeto a un plazo (generalmente extenso) .", "Permite al particular adueñarse definitivamente del bien.", "Se otorga solo para necesidades vitales como beber agua."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué se entiende por "alineación" en materia de vías públicas?', '["La pavimentación de una calle nueva.", "La operación por la cual la Administración fija el límite entre la vía pública y los predios colindantes .", "El cobro de peaje en las autopistas.", "La iluminación nocturna de las avenidas."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿A quién corresponde el dominio originario de los recursos naturales según el art. 124 CN?', '["Al Estado Nacional exclusivamente.", "A las Provincias .", "A las empresas internacionales que los explotan.", "Al Banco Central de la República Argentina."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué determinó la CSJN respecto al derecho sobre una sepultura en un cementerio público?', '["Que es un derecho real de dominio privado.", "Que consiste en una concesión de uso sobre un bien de dominio público .", "Que es un derecho que se extingue al año de fallecida la persona.", "Que los cementerios no pertenecen a ninguna jurisdicción estatal."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Por qué rama del derecho se rigen las restricciones impuestas al dominio privado solo en el interés público?', '["Por el Derecho Civil.", "Por el Derecho Administrativo .", "Por el Derecho Penal.", "Por el Derecho Internacional Público."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es un carácter de las restricciones administrativas?', '["Son siempre indemnizables.", "Son generales, actuales, permanentes y no indemnizables .", "Solo pueden imponerse por contrato.", "Tienen una duración máxima de dos años."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué es una servidumbre administrativa?', '["Una prohibición de edificar a más de dos metros.", "Un derecho real administrativo constituido por el Estado sobre un bien para que sea usado por el público .", "La venta forzosa de un campo al Estado.", "El pago de un impuesto inmobiliario municipal."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es una diferencia clave entre restricción y servidumbre administrativa?', '["La restricción es un derecho real y la servidumbre no.", "La restricción no genera indemnización; la servidumbre sí por implicar una desmembración del dominio .", "Las restricciones son solo para inmuebles y las servidumbres para muebles.", "Las servidumbres son siempre temporales y las restricciones perpetuas."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué es el "camino de sirga" según el CCyC?', '["Una servidumbre de paso para ganado.", "Una franja de 15 metros que el dueño colindante a un cauce apto para transporte debe dejar libre .", "Un impuesto al transporte marítimo.", "La zona donde se instalan los puertos nacionales."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es la autoridad competente en materia de servidumbre de electroducto a nivel federal?', '["El Ministerio de Salud.", "El Ente Nacional Regulador de la Electricidad (ENRE) .", "La Inspección General de Justicia.", "Las municipalidades únicamente."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿En qué consiste la "requisición" o "requisa"?', '["En la compra de insumos de oficina por el Estado.", "En la ocupación o adquisición coactiva de un bien por el Estado para satisfacer una situación general .", "En el embargo preventivo de las cuentas de un funcionario.", "En la donación de sangre obligatoria."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué prohíbe el art. 17 de la Constitución Nacional respecto a la requisición?', '["Que la realice el Poder Judicial.", "Que sea efectuada por \\\"cuerpos armados\\\" (fuerzas irregulares) .", "Que sea indemnizada.", "Que recaiga sobre bienes muebles."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué es el "decomiso" en el ámbito administrativo?', '["Un préstamo de bienes del Estado a particulares.", "Una sanción de policía que produce la pérdida definitiva de una cosa mueble por razones de seguridad o moralidad .", "La inauguración de una plaza.", "El retiro de la estatua de un prócer."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué es la "ocupación temporánea"?', '["La expropiación definitiva de un inmueble.", "La adquisición provisional y transitoria de un bien ajeno para utilidad pública sin pérdida del dominio .", "El alquiler de un local para oficinas públicas por 10 años.", "La invasión de tierras por parte de ciudadanos extranjeros."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cómo se define la expropiación según Marienhoff?', '["Como un contrato de compraventa forzosa.", "Como el medio jurídico para transferir un bien de un patrimonio a otro por utilidad pública, previa indemnización .", "Como un castigo al propietario que no usa su bien.", "Como la estatización de todos los medios de producción."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es la naturaleza jurídica de la expropiación?', '["Es una institución de derecho privado regida por el CCyC.", "Es una institución jurídica de base constitucional y regida por el derecho público .", "Es un acto administrativo de alcance general sin revisión judicial.", "Es un contrato bilateral entre el expropiante y el expropiado."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué requisito constitucional exige el art. 17 para que proceda la expropiación?', '["Solo la voluntad del Presidente.", "Que sea calificada por ley y previamente indemnizada .", "Que el propietario esté de acuerdo con el precio.", "Que el bien esté abandonado por más de 10 años."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué tipo de bienes son expropiables según la ley 21.499?', '["Solo los inmuebles de los particulares.", "Únicamente los bienes del dominio privado del Estado.", "Todos los bienes convenientes o necesarios para la utilidad pública, sean cosas o no .", "Solo el dinero en efectivo de las cuentas bancarias."]'::jsonb, 2, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Quiénes pueden actuar como sujetos expropiantes?', '["Solo el Estado Nacional.", "El Estado Nacional, CABA, entidades autárquicas, empresas del Estado y particulares autorizados por ley .", "Cualquier ciudadano que declare un bien de utilidad pública.", "Únicamente los jueces federales."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué comprende la indemnización expropiatoria según el art. 10 de la ley?', '["El valor afectivo y las ganancias hipotéticas.", "El valor objetivo del bien y los daños que sean consecuencia directa e inmediata .", "El lucro cesante en todos los casos.", "El mayor valor que la obra pública le dará al bien en el futuro."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿En qué forma debe pagarse la indemnización expropiatoria por regla general?', '["En bonos del Estado a 20 años.", "En dinero efectivo .", "Mediante el canje por otros terrenos fiscales.", "Con descuentos en el pago de impuestos futuros."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué es el "avenimiento expropiatorio"?', '["El inicio de la demanda judicial de expropiación.", "El acuerdo extrajudicial entre el expropiante y el propietario sobre el valor del bien .", "La renuncia del Estado a expropiar el bien.", "El desalojo por la fuerza pública del inmueble."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué "premio" otorga la ley al propietario que acepta el avenimiento en bienes inmuebles?', '["Una exención de impuestos de por vida.", "Un incremento automático del 10% sobre el valor máximo estimado .", "El derecho a elegir otro terreno del Estado.", "Una pensión graciable."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es la función del Tribunal de Tasaciones de la Nación?', '["Dictar la ley de utilidad pública.", "Establecer los valores objetivos de los bienes sujetos a expropiación .", "Juzgar los delitos cometidos por los expropiados.", "Administrar los hospitales públicos expropiados."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuándo queda perfeccionada la expropiación en sede judicial?', '["Con el solo dictado de la ley de utilidad pública.", "Con la transferencia del dominio mediante sentencia firme, toma de posesión y pago de la indemnización .", "Cuando el expropiado recibe la notificación de la demanda.", "Al momento de iniciarse las obras públicas en el terreno."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué es la "expropiación irregular"?', '["Una expropiación realizada sin ley del Congreso.", "Aquella que inicia el expropiado contra el Estado cuando este toma el bien sin pagar o limita indebidamente el dominio .", "El robo de materiales de una obra pública.", "Una expropiación de bienes extranjeros."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿En qué caso procede la acción de "retrocesión"?', '["Cuando el Estado paga más de lo debido por el bien.", "Cuando al bien expropiado se le da un destino diferente al previsto o no se le da destino en dos años .", "Cuando el expropiado decide que quiere recuperar su bien pagando el doble.", "Cuando la ley de utilidad pública es derogada antes de la desposesión."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué requisito debe cumplir el expropiado para lograr la retrocesión?', '["No debe hacer nada, el Estado le devuelve el bien gratis.", "Debe reintegrar la indemnización percibida con la actualización que corresponda .", "Debe demostrar que el Estado tiene mucho dinero.", "Debe construir una escuela en el terreno recuperado."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es el plazo de prescripción para la acción de retrocesión?', '["No tiene plazo, es imprescriptible.", "Tres años computados desde que el bien debió recibir su destino .", "Cinco años desde la compra.", "Diez años desde la ocupación."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es el carácter de la responsabilidad del Estado según la doctrina y jurisprudencia actual?', '["Indirecta y subjetiva (basada en la culpa).", "Objetiva y directa .", "Solo responde si hay dolo del funcionario.", "El Estado es irresponsable por dogma divino."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué establecía el "dogma de la irresponsabilidad" histórica del Estado?', '["Que el Estado debe pagar siempre todos los daños.", "Que el Rey no podía equivocarse y por ende el Estado no era demandable .", "Que solo los jueces eran responsables de sus actos.", "Que la responsabilidad era puramente contractual."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál fue el primer caso (1864) donde la CSJN reconoció la responsabilidad contractual del Estado?', '["\\\"Tomás Devoto\\\".", "\\\"Bates Stokes y Cia\\\" .", "\\\"Ferrocarril Oeste\\\".", "\\\"Vadell\\\"."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué requería la "Teoría del Fisco" para poder demandar al Estado?', '["Que el acto fuera de imperio.", "Que el litigio tuviera carácter patrimonial (en la persona del Fiscus) .", "Que el funcionario fuera condenado penalmente antes.", "El permiso previo del Papa."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es un recaudo esencial para la existencia de responsabilidad del Estado?', '["La intención de dañar del funcionario.", "La efectiva existencia de daño resarcible acreditado por el perjudicado .", "Que el daño sea mayor a un millón de pesos.", "Que el damnificado sea empleado público."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿En qué consiste el factor de atribución "falta de servicio"?', '["En que el funcionario se olvidó de ir a trabajar.", "En una violación o anormalidad frente a las obligaciones del servicio regular .", "En la falta de presupuesto para pagar sueldos.", "En el maltrato verbal de un empleado administrativo."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué reconoció la CSJN en el caso "Tomás Devoto" (1933)?', '["La irresponsabilidad absoluta del Estado.", "La responsabilidad indirecta y subjetiva del Estado por hechos de sus dependientes .", "Que las chispas de un brasero no causan daños.", "La nulidad de la Constitución Nacional."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué importancia tiene el caso "Vadell" (1984) en la evolución de la responsabilidad estatal?', '["Volvió al criterio de irresponsabilidad.", "Consagró la responsabilidad objetiva y directa receptando el concepto de \\\"falta de servicio\\\" .", "Determinó que el Registro de la Propiedad es privado.", "Estableció que solo se indemniza el daño moral."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Es indemnizable el lucro cesante en la responsabilidad por ACTIVIDAD LEGÍTIMA según la ley 26.944?', '["Sí, siempre.", "En ningún caso procede la reparación del lucro cesante por actividad legítima .", "Solo si el damnificado es una empresa multinacional.", "Solo si lo autoriza el Congreso por ley especial."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué requisito exige la ley 26.944 para que proceda la responsabilidad por actividad legítima?', '["Que la ley sea inconstitucional.", "Un sacrificio especial en la persona dañada, diferenciado del resto de la comunidad .", "Que el Estado haya actuado con malicia.", "Que el daño haya ocurrido en tiempo de guerra."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Responde el Estado por los daños causados por una ley declarada inconstitucional?', '["No, porque el legislador es soberano.", "Sí, se trata de una conducta legislativa ilícita e indemnizable en plenitud .", "Solo si la ley fue votada por unanimidad.", "Únicamente si el Presidente no la vetó."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cómo se define el "error judicial" para solicitar indemnización?', '["Cualquier sentencia que el particular pierda.", "Aquel provocado de modo irreparable que no pudo cesar por medios procesales ordinarios .", "La demora de un mes en dictar una providencia.", "El mal carácter de un secretario de juzgado."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué sucede con la responsabilidad por actividad judicial legítima?', '["Genera siempre derecho a indemnización.", "No genera derecho a indemnización según la ley 26.944 .", "Se paga con un sueldo del juez.", "Es tratada como un contrato administrativo."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué es la "confianza legítima" derivada del principio de buena fe contractual?', '["El derecho a cobrar sin trabajar.", "La imposibilidad del Estado de actuar en contradicción con sus propios actos precedentes que generaron expectativas .", "La obligación de creer todo lo que dice el funcionario.", "Un seguro que pagan los contratistas."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué es el "rescate" en materia de contratos administrativos?', '["Salvar a una persona de una inundación.", "La reasunción de la actividad u obra por parte del Estado por razones de mérito o conveniencia .", "El pago de la deuda externa por particulares.", "La prórroga de una concesión por 50 años."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cómo define Gordillo al procedimiento administrativo?', '["Como un juicio ante tribunales de la administración.", "Como la parte del derecho que estudia las reglas para la intervención de interesados en la voluntad administrativa .", "Como un conjunto de leyes penales aplicables a funcionarios.", "Como una sugerencia no obligatoria para el Estado."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es el "cauce formal" de la función administrativa?', '["El proceso judicial.", "El procedimiento administrativo .", "La charla informal con el Intendente.", "Los medios de comunicación."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es una función del procedimiento administrativo?', '["Recaudar multas de tránsito.", "Función garantista de los derechos de los interesados y legitimadora de las resoluciones .", "Ocultar la información pública.", "Retrasar las decisiones del Estado."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿En qué consiste el principio de "Impulso de Oficio"?', '["En que el particular debe mover el expediente todos los días.", "En que la impulsión del procedimiento corresponde en todos los casos a la administración .", "En que el expediente se mueve solo si hay presupuesto.", "En que el juez penal debe vigilar el trámite."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué diferencia la "Verdad Material" de la "Verdad Formal"?', '["No hay diferencia, son sinónimos.", "La material obliga a la administración a ajustarse a los hechos reales, aunque no hayan sido probados por el particular .", "La material solo existe en los juicios de divorcio.", "La formal es la que decide el Presidente por decreto."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿A favor de quién opera el principio del "Informalismo"?', '["Exclusivamente a favor de la Administración Pública.", "Solo a favor del administrado (excusa inobservancia de formas no esenciales) .", "De ambos por igual.", "Únicamente de los abogados matriculados."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué garantiza el "Debido Proceso Admnistrativo" (Derecho a ser oído)?', '["El derecho a gritar en las oficinas públicas.", "Exposer razones, ofrecer/producir pruebas y obtener una decisión fundada .", "El derecho a que el Estado le pague el abogado al particular.", "La obligación de confesar delitos administrativos."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es la regla sobre las "Costas" en el procedimiento administrativo?', '["El que pierde el recurso paga todos los gastos.", "No existe condena en costas; cada parte paga sus gastos e impuestos .", "El Estado siempre paga los honorarios del abogado del particular.", "El abogado del Estado cobra una comisión del particular."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cómo es el ejercicio de la competencia administrativa?', '["Es opcional y prorrogable por acuerdo de partes.", "Es una obligación de la autoridad y es improrrogable (salvo delegación o sustitución autorizada) .", "Solo se ejerce si el particular paga una tasa.", "Puede ser delegada en empresas privadas sin ley previa."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué es la "Avocación"?', '["El traspaso de competencia a un inferior.", "El ejercicio por parte del superior jerárquico de competencia que corresponde al inferior .", "La renuncia del funcionario a su cargo.", "El pedido de informes a la Fiscalía de Estado."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es el máximo organismo de asesoramiento jurídico del Poder Ejecutivo Nacional?', '["La Corte Suprema de Justicia.", "La Procuración del Tesoro de la Nación .", "El Colegio de Abogados.", "La Facultad de Derecho."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Quién tiene a su cargo la defensa del patrimonio del Fisco en la Provincia de Buenos Aires?', '["El Gobernador.", "El Fiscal de Estado .", "El Asesor General de Gobierno.", "El Defensor del Pueblo."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué es el "Expediente Administrativo"?', '["Una serie de llamadas telefónicas.", "La acumulación sistemática de constancias escritas de actos y trámites .", "Un libro secreto del Presidente.", "Únicamente la demanda judicial."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es el plazo máximo de fojas para cada cuerpo de un expediente en PBA?', '["100 fojas.", "200 fojas .", "500 fojas.", "No tiene límite."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cómo deben ser redactados los escritos ante la Administración en PBA?', '["En cualquier idioma extranjero con subtítulos.", "A máquina o manuscritos en tinta, en idioma nacional y legibles .", "Solo mediante dibujos y esquemas.", "Únicamente por correo electrónico personal."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué sucede en caso de duda sobre la autenticidad de una firma en un escrito?', '["Se rechaza el escrito inmediatamente.", "La autoridad puede llamar al interesado para que ratifique la firma en su presencia .", "Se envía al interesado a prisión preventiva.", "Se acepta el escrito como válido sin más trámite por informalismo."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Rige la libertad probatoria en el procedimiento administrativo?', '["No, solo se acepta la prueba documental.", "Sí, debe admitirse cualquier tipo de prueba que no afecte la moral o libertad .", "Solo se acepta la confesión bajo juramento.", "Depende de si el funcionario está de buen humor."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es la regla general sobre el "Silencio Administrativo"?', '["Que significa aceptación de lo pedido.", "Que tiene carácter negativo (denegación tácita) .", "Que interrumpe la prescripción de los delitos penales.", "Que obliga al funcionario a renunciar."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es un requisito esencial del acto administrativo según el art. 7 de la ley 19.549?', '["Que sea dictado por un particular.", "Competencia, Causa, Objeto, Procedimientos, Motivación y Finalidad .", "Que sea secreto y no se notifique.", "Que tenga una duración de 100 años."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué debe contener obligatoriamente una notificación para ser válida?', '["Solo la firma del cadete.", "Íntegramente los fundamentos y la parte dispositiva del acto .", "Un resumen hecho por un periodista.", "El sello de la oficina de correos únicamente."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cómo se cuentan los plazos en el procedimiento administrativo?', '["Por días corridos incluyendo feriados.", "Por días hábiles administrativos .", "Según el calendario lunar.", "Por horas desde el momento de la firma."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es el plazo de gracia en la Provincia de Buenos Aires?', '["Las dos primeras horas del día siguiente.", "Las cuatro primeras horas de atención de la repartición .", "Todo el día siguiente al vencimiento.", "No existe plazo de gracia en la provincia."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué recurso procede ante el mismo órgano que dictó el acto en el ámbito nacional?', '["Recurso Jerárquico.", "Recurso de Reconsideración .", "Recurso de Alzada.", "Recurso Extraordinario."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es la regla general para la selección del cocontratante estatal (Licitación)?', '["La contratación directa siempre.", "La licitación pública o concurso público .", "El sorteo ante escribano.", "La elección por el gremio mayoritario."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué diferencia la licitación del concurso?', '["La licitación es gratuita y el concurso pago.", "La licitación se basa en el factor económico; el concurso en aspectos técnicos o artísticos .", "El concurso es solo para modelos y la licitación para empresas.", "No existe ninguna diferencia legal."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué es el "Pliego de Bases y Condiciones"?', '["Una invitación a una fiesta oficial.", "El documento que regula el procedimiento licitatorio y el futuro contrato .", "Una lista de precios de supermercado.", "El currículum vitae del funcionario contratante."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué garantiza la "Estabilidad del Empleado Público" según la CN?', '["El derecho a no trabajar nunca.", "La facultad de conservar el cargo mientras no haya una causal legal de extinción .", "Un aumento de sueldo cada mes por decreto.", "El derecho a heredar el cargo a los hijos."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es el órgano encargado de examinar y aprobar las cuentas públicas en PBA?', '["El Banco Provincia.", "El Tribunal de Cuentas .", "La Legislatura exclusivamente.", "La Dirección General de Escuelas."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué sistema de control adoptó la Argentina en 1853 (trial against the State)?', '["Sistema administrativo (tipo francés).", "Sistema judicialista (tipo norteamericano) .", "Sistema monárquico de indemandabilidad.", "Control por jurados populares."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué estableció la CSJN en el caso "Pietranera" (1966) sobre sentencias contra el Estado?', '["Que el Estado no debe cumplir las sentencias nunca.", "Que el carácter declarativo de la sentencia no autoriza al Estado a no cumplirla .", "Que las deudas del Estado se pagan con tierras.", "Que solo se pagan sentencias de menos de 100 pesos."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué es el CIADI?', '["Un club de fútbol internacional.", "El Centro Internacional de Arreglo de Diferencias sobre Inversiones (arbitraje) .", "Una oficina de la AFIP para extranjeros.", "La Confederación Internacional de Abogados de Derecho Administrativo."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es el plazo de caducidad para demandar judicialmente un acto administrativo nacional?', '["10 años como en el derecho civil.", "Noventa (90) días hábiles judiciales .", "Un mes calendario.", "Es imprescriptible."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué pretensión busca que el Estado realice una conducta positiva para efectivizar un derecho social?', '["Pretensión anulatoria.", "Pretensión prestacional .", "Pretensión indemnizatoria.", "Pretensión de lesividad."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Cuál es la vía sumarísima para garantizar derechos vulnerados de raigambre constitucional?', '["Juicio Ordinario.", "Acción de Amparo .", "Recurso de Queja.", "Denuncia de Ilegitimidad."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10126', 'Derecho Administrativo II', 'media', '¿Qué plazo fija la ley 13.928 de PBA para deducir la acción de amparo?', '["24 horas desde el hecho.", "Treinta (30) días desde el conocimiento del acto u omisión .", "Un año.", "No tiene plazo de caducidad."]'::jsonb, 1, 'Conforme al régimen normativo y la Cátedra de Derecho Administrativo II.', 100);